<?php
namespace App\Services\Shipping;
use App\Services\Shipping\Diagnostics\XpertaContractInspector;
final class ProviderStrategyResolver { public function __construct(private XpertaContractInspector $xperta){} public function resolve(string $operation,string $carrier='estafeta',string $environment='stage'):array{$operation=strtolower($operation);$reasons=[];if(strtolower($carrier)!=='estafeta')return['strategy'=>'unavailable','reasons'=>['carrier_not_supported']];if($environment==='production')return['strategy'=>'unavailable','reasons'=>['production_blocked_in_est_prd_03']];if($operation==='auth'&&config('zigo_estafeta.contracts.auth')==='confirmed')return['strategy'=>'estafeta_direct','http_provider'=>'estafeta','reasons'=>['direct_auth_contract_confirmed']];$x=$this->xperta->inspect();$contract=(bool)($x['contracts'][$operation]['confirmed']??false);$configured=$this->xpertaConfigured();$operationEnabled=$operation!=='coverage'||(bool)config('services.xperta.frequency_enabled',false);if(in_array($operation,['quote','coverage'],true)&&$contract&&$operationEnabled&&config('services.xperta.enabled',false)&&$configured)return['strategy'=>'xperta_estafeta','http_provider'=>'xperta','reasons'=>['confirmed_xperta_contract','ltd_estafeta','xperta_enabled']];if($operation==='quote'&&config('zigo_provider_rates.engine_v2_enabled',false))return['strategy'=>'contractual_local','http_provider'=>'none','reasons'=>['local_rate_engine_enabled']];if($operation==='tracking')return['strategy'=>'legacy_estafeta','http_provider'=>'estafeta','reasons'=>['legacy_tracking_contract_confirmed']];if(!$contract)$reasons[]=$operation.'_contract_unknown';if(!$operationEnabled)$reasons[]='xperta_'.$operation.'_disabled';if(!$configured)$reasons[]='xperta_credentials_missing';if(!config('services.xperta.enabled',false))$reasons[]='xperta_disabled';return['strategy'=>'unavailable','http_provider'=>'none','reasons'=>$reasons];}
 private function xpertaConfigured():bool{foreach(['base_url','empresa','corporativo','email','password','api_key'] as $key)if(blank(config('services.xperta.'.$key)))return false;return true;}}
